-- Restore order: functions (02) first, then this file (its triggers call them).
CREATE TABLE public.workout_invites (
  id uuid DEFAULT uuid_generate_v4() NOT NULL,
  sender_id uuid,
  recipient_id uuid,
  scheduled_for timestamp with time zone NOT NULL,
  message text,
  status text DEFAULT 'pending'::text,
  created_at timestamp with time zone DEFAULT now(),
  updated_at timestamp with time zone DEFAULT now(),
  CONSTRAINT workout_invites_pkey PRIMARY KEY (id),
  CONSTRAINT workout_invites_recipient_id_fkey FOREIGN KEY (recipient_id) REFERENCES user_profiles(id) ON DELETE CASCADE,
  CONSTRAINT workout_invites_sender_id_fkey FOREIGN KEY (sender_id) REFERENCES user_profiles(id) ON DELETE CASCADE,
  CONSTRAINT workout_invites_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'declined'::text])))
);
CREATE INDEX idx_workout_invites_recipient ON public.workout_invites USING btree (recipient_id);
CREATE INDEX idx_workout_invites_status ON public.workout_invites USING btree (status);
ALTER TABLE public.workout_invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users can delete their own invites" ON public.workout_invites FOR DELETE USING ((auth.uid() = sender_id));
CREATE POLICY "Users can send invites" ON public.workout_invites FOR INSERT WITH CHECK ((auth.uid() = sender_id));
CREATE POLICY "Users can update their own invites" ON public.workout_invites FOR UPDATE USING (((auth.uid() = sender_id) OR (auth.uid() = recipient_id))) WITH CHECK (((auth.uid() = sender_id) OR (auth.uid() = recipient_id)));
CREATE POLICY "Users can view their own invites" ON public.workout_invites FOR SELECT USING (((auth.uid() = sender_id) OR (auth.uid() = recipient_id)));
CREATE TRIGGER on_workout_invite AFTER INSERT ON public.workout_invites FOR EACH ROW WHEN ((new.status = 'pending'::text)) EXECUTE FUNCTION notify_workout_invite();
CREATE TRIGGER on_workout_invite_response AFTER UPDATE ON public.workout_invites FOR EACH ROW EXECUTE FUNCTION notify_workout_invite_response();
REVOKE ALL ON public.workout_invites FROM PUBLIC;
GRANT SELECT ON public.workout_invites TO anon;
GRANT DELETE, INSERT, SELECT, UPDATE ON public.workout_invites TO authenticated;
GRANT ALL ON public.workout_invites TO service_role;
